T NULL,    "role" "UserRole" NOT NULL,    "isEmailVerified" BOOLEAN NOT NULL DEFAULT false,    "isActive" BOOLEAN NOT NULL DEFAULT true,    "lastLoginAt" TIMESTAMP(3),    "deletedAt" TIMESTAMP(3),    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,    "updatedAt" TIMESTAMP(3) NOT NULL,    CONSTRAINT "User_pkey" PRIMARY KEY ("id"));-- CreateTableCREATE TABLE "Hospital" (    "id" UUID NOT NULL,    "userId" UUID NOT NULL,    "verificationStatus" "VerificationStatus" NOT NULL DEFAULT 'PENDING',    "profileCompleted" BOOLEAN NOT NULL DEFAULT false,    "verifiedAt" TIMESTAMP(3),    "deletedAt" TIMESTAMP(3),    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,    "updatedAt" TIMESTAMP(3) NOT NULL,    CONSTRAINT "Hospital_pkey" PRIMARY KEY ("id"));-- CreateTableCREATE TABLE "HospitalProfile" (    "id" UUID NOT NULL,    "hospitalId" UUID NOT NULL,    "legalName" VARCHAR(255) NOT NULL,    "displayName" VARCHAR(255) NOT NULL,    "registrationNumber" VARCHAR(100) NOT NULL,    "hospitalType" "HospitalType" NOT NULL,    "ownershipType" "OwnershipType" NOT NULL,    "licenseNumber" VARCHAR(100),    "licenseExpiresAt" TIMESTAMP(3),    "addressLine1" VARCHAR(255) NOT NULL,    "addressLine2" VARCHAR(255),    "city" VARCHAR(100) NOT NULL,    "state" VARCHAR(100) NOT NULL,    "country" CHAR(2) NOT NULL DEFAULT 'IN',    "postalCode" VARCHAR(20),    "latitude" DECIMAL(9,6) NOT NULL,    "longitude" DECIMAL(9,6) NOT NULL,    "emergencyPhone" VARCHAR(30) NOT NULL,    "emergencyEmail" VARCHAR(320),    "website" VARCHAR(2048),    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,    "updatedAt" TIMESTAMP(3) NOT NULL,    CONSTRAINT "HospitalProfile_pkey" PRIMARY KEY ("id"));-- CreateTableCREATE TABLE "HospitalInfrastructure" (    "id" UUID NOT NULL,    "hospitalId" UUID NOT NULL,    "totalBeds" INTEGER NOT NULL DEFAULT 0,    "availableBeds" INTEGER NOT NULL DEFAULT 0,    "totalIcuBeds" INTEGER NOT NULL DEFAULT 0,    "availableIcuBeds" INTEGER NOT NULL DEFAULT 0,