LE "HospitalEquipment" (    "id" UUID NOT NULL,    "hospitalId" UUID NOT NULL,    "equipmentTypeId" UUID NOT NULL,    "totalQuantity" INTEGER NOT NULL DEFAULT 0,    "availableQuantity" INTEGER NOT NULL DEFAULT 0,    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,    "updatedAt" TIMESTAMP(3) NOT NULL,    CONSTRAINT "HospitalEquipment_pkey" PRIMARY KEY ("id"));-- CreateTableCREATE TABLE "HospitalResource" (    "id" UUID NOT NULL,    "hospitalId" UUID NOT NULL,    "kind" "ResourceKind" NOT NULL,    "totalQuantity" INTEGER NOT NULL DEFAULT 0,    "availableQuantity" INTEGER NOT NULL DEFAULT 0,    "reservedQuantity" INTEGER NOT NULL DEFAULT 0,    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,    "updatedAt" TIMESTAMP(3) NOT NULL,    CONSTRAINT "HospitalResource_pkey" PRIMARY KEY ("id"));-- CreateTableCREATE TABLE "user" (    "id" UUID NOT NULL,    "userId" UUID NOT NULL,    "firstName" VARCHAR(100) NOT NULL,    "lastName" VARCHAR(100),    "phone" VARCHAR(30),    "dateOfBirth" TIMESTAMP(3),    "bloodGroup" VARCHAR(5),    "emergencyContactName" VARCHAR(200),    "emergencyContactPhone" VARCHAR(30),    "deletedAt" TIMESTAMP(3),    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,    "updatedAt" TIMESTAMP(3) NOT NULL,    CONSTRAINT "user_pkey" PRIMARY KEY ("id"));-- CreateTableCREATE TABLE "EmergencyRequest" (    "id" UUID NOT NULL,    "userId" UUID NOT NULL,    "description" TEXT,    "latitude" DECIMAL(9,6) NOT NULL,    "longitude" DECIMAL(9,6) NOT NULL,    "radiusMeters" INTEGER NOT NULL,    "status" "EmergencyStatus" NOT NULL DEFAULT 'CREATED',    "selectedHospitalId" UUID,    "acceptedAt" TIMESTAMP(3),    "selectedAt" TIMESTAMP(3),    "cancelledAt" TIMESTAMP(3),    "completedAt" TIMESTAMP(3),    "deletedAt" TIMESTAMP(3),    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,    "updatedAt" TIMESTAMP(3) NOT NULL,    CONSTRAINT "EmergencyRequest_pkey" PRIMARY KEY ("id"));-- CreateTableCREATE TABLE "EmergencyRequirement" (    "id